def compute(vars):
    ages = [vars["v1"], vars["v2"]]
    average_age = sum(ages) / len(ages)
    return {
        "value": average_age,
        "trace": {
            "ages": ages,
            "count": len(ages),
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "years"
            }
        }
    }
